INSERT INTO `Znacky` (_id,category,identifier,name,image,description) VALUES (1,0,'B1','Zákaz vjazdu všetkých vozidiel (v oboch smeroch)','b1','Značka Zákaz vjazdu všetkých vozidiel v oboch smeroch (č. B 1) zakazuje vjazd všetkým druhom vozidiel v oboch smeroch jazdy.');
INSERT INTO `Znacky` (_id,category,identifier,name,image,description) VALUES (2,1,'P1','Daj prednosť v jazde','p1','Značka Daj prednosť v jazde! (č. P 1) ukladá vodičovi povinnosť dať prednosť v jazde; označuje vedľajšiu cestu pred križovatkou s hlavnou cestou. Značka sa používa najmä v kombinácii s príslušnou dodatkovou tabuľkou s tvarom križovatky Tvar križovatky č. P 13 až P 15.');
INSERT INTO `Znacky` (_id,category,identifier,name,image,description) VALUES (3,1,'P2','Stoj, daj prednosť v jazde','p2','Značka Stoj, daj prednosť v jazde! (č. P 2) ukladá vodičovi povinnosť zastaviť vozidlo a dať prednosť v jazde; vodič je povinný zastaviť vozidlo na takom mieste, odkiaľ má na križovatku náležitý rozhľad. Značka označuje vedľajšiu cestu pred križovatkou s hlavnou cestou, a to najmä v prípadoch, keď križovatka nie je dostatočne prehľadná; za predpokladu, že miesto na zastavenie vozidla je možné presne vymedziť, použije sa značka v kombinácii so značkou č. V 5c. Značka č. P 2 sa používa najmä v kombinácii s príslušnou dodatkovou tabuľkou s tvarom križovatky Tvar križovatky č. P 13 až P 15. Ako predbežná značka sa k značke č. P 2 používa značka č. P 1 s dodatkovou tabuľkou č. E 2 s uvedením skutočnej vzdialenosti k miestu, na ktoré sa vzťahuje povinnosť zastaviť vozidlo; na uvedenie tejto skutočnej vzdialenosti možno použiť i značku č. V 14. Značka č. P 2 sa používa aj pred železničným priecestím v prípadoch, keď je potrebné vodičovi prikázať v záujme bezpečnosti premávky zastaviť vozidlo.');
INSERT INTO `Znacky` (_id,category,identifier,name,image,description) VALUES (4,2,'P8','Hlavná cesta','p8','Značka Hlavná cesta (č. P 8) upozorňuje najmä v obci na križovatku s vedľajšou cestou a označuje hlavnú cestu. Používa sa v kombinácii najmä s príslušnou dodatkovou tabuľkou s tvarom križovatky Tvar križovatky č. P 13 až P 15.');
INSERT INTO `Znacky` (_id,category,identifier,name,image,description) VALUES (5,1,'P4','Križovatka kde prednosť v jazde nieje upravená značkami','p4','Križovatka kde prednosť v jazde nieje upravená značkami');
